      game = Game.create_for!(Quiz.find(params[:quiz_id]))
      redirect_to moderate_game_path(game), status: :see_other
    end

    def show
      prepare_screen
    end

    def advance
      @game.advance!(from: params[:version])
      respond_to_control
    end

    def winners
      mode = params[:mode]
      return head :bad_request unless %w[top draw reset].include?(mode)
      @game.select_winners!(mode)
      respond_to_control
    end

