      def respond_to_control
        if request.xhr?
          render_screen
        else
          redirect_to moderate_game_path(@game), status: :see_other
        end
      end

      def load_game
        @game = Game.find(params[:id])
      end

      def prepare_screen
        @leaderboard = @game.leaderboard if @game.ended?
        @round = @game.current_round
        @tallies = @round.answers.group(:option_index).count if @game.closed?
        @counter = counter
      end

      def counter
        if @game.lobby?
          "Players: #{@game.present_players.count}"
        elsif @game.open?
          answered = Answer.where(game_round_id: @game.rounds.where(number: @game.round_number).select(:id)).count
          "Answers: #{answered} / #{@game.present_players.count}"
        end
      end

      def render_screen
        prepare_screen
        render partial: "screen"
      end
  end
