module Moderate
  class QuizzesController < BaseController
    before_action :load_quiz, only: %i[show edit update destroy export]

    def index
      @quizzes = Quiz.order(:id)
      @question_counts = Question.group(:quiz_id).count
    end

    def show
      @questions = @quiz.questions.to_a
    end

    def export
      @quiz_json = QuizDocument.export(@quiz)
    end

    def new
      @quiz = Quiz.new
      render :form
    end

    def edit
      render :form
    end

    def create
      @quiz = Quiz.new(quiz_params)
      save_quiz
    end

    def update
      @quiz.assign_attributes(quiz_params)
      save_quiz
    end

    def destroy
      @quiz.destroy!
      redirect_to moderate_root_path, status: :see_other
    end

    private
      def load_quiz
        @quiz = Quiz.find(params[:id])
      end

      def quiz_params
        params.expect(quiz: [ :title, :number_of_winners ])
      end

      def save_quiz
        if @quiz.save
          redirect_to moderate_quiz_path(@quiz), status: :see_other
        else
          render :form, status: :unprocessable_content
        end
      end
  end
end
