// SQLite is authoritative. Cable messages carry no quiz content: after a phase
// or prize change (or reconnect), each client requests its own screen. Joining,
// voting and moderator controls use ordinary CSRF-protected Rails forms.
function setupLiveGame(root) {
  const phone = !!root.dataset.leaveUrl;
  const tab = Array.from(crypto.getRandomValues(new Uint8Array(16)), n => n.toString(16).padStart(2, "0")).join("");
  const csrf = document.querySelector("meta[name=csrf-token]")?.content;
  const note = document.querySelector("[data-network-note]");
  const state = () => root.querySelector("[data-version]");
  const ended = () => state().hasAttribute("data-ended");
  let consumer, timer, connected = false, away = false, syncQueued = false;
  let requests = Promise.resolve(), failures = 0, lastPulse = 0;

  function schedule(delay) {
    clearTimeout(timer);
    if (away) return;
    // A crowded room should not produce waves of synchronized retries. If
    // WebSockets are blocked, the same tiny sync request doubles as a poll.
    const hasCounter = !phone && root.querySelector("[data-counter]");
    const interval = connected ? (hasCounter ? 850 : 21000) : 450;
    const base = failures ? Math.min(15000, 1000 * 2 ** Math.min(failures, 4)) : interval;
    timer = setTimeout(sync, delay ?? base * (1 + Math.random() * 0.2));
  }

  function enqueue(work) {
    // In particular, serialize rapid answer changes in the order tapped. A
    // slow sync must never repaint the page *after* a newer action response.
    requests = requests.then(async () => {
      if (away) return;
      try {
        await work();
        failures = 0;
        note.hidden = true;
      } catch (error) {
        failures++;
        note.textContent = "Connection interrupted. Reconnecting… Check your last choice.";
        note.hidden = false;
      } finally {
        schedule();
      }
    });
  }

  async function update(path, method, fields, pulse) {
    const url = new URL(path, location.origin);
    const options = { method, cache: "no-store", headers: { "X-Requested-With": "XMLHttpRequest", Accept: "text/html" }, signal: AbortSignal.timeout(12000) };
    if (method === "GET") {
      url.search = fields;
    } else {
      if (csrf) options.headers["X-CSRF-Token"] = csrf;
      if (phone && pulse) fields.set("tab", tab);
      options.body = fields;
    }
    const response = await fetch(url, options);
    if (!response.ok && response.status !== 422) throw new Error("Unable to sync");
    if (phone && pulse) lastPulse = Date.now();
    if (response.status === 204 || away) return;
    if (response.headers.get("Content-Type")?.includes("application/json")) {
      const { counter } = await response.json();
      const pill = root.querySelector("[data-counter]");
      if (pill && pill.textContent !== counter) pill.textContent = counter;
    } else {
      const template = document.createElement("template");
      template.innerHTML = await response.text();
      if (!template.content.firstElementChild?.hasAttribute("data-version")) throw new Error("Missing game state");
      root.replaceChildren(template.content);
    }
  }

  function sync() {
    if (away || syncQueued) return;
    syncQueued = true;
    enqueue(async () => {
      syncQueued = false;
      await update(root.dataset.syncUrl, phone ? "POST" : "GET",
        new URLSearchParams({ version: state().dataset.version }), Date.now() - lastPulse >= 20000);
    });
  }

  root.addEventListener("submit", event => {
    event.preventDefault();
    const form = event.target;
    const fields = new URLSearchParams(new FormData(form));
    if (event.submitter?.name) fields.set(event.submitter.name, event.submitter.value);
    enqueue(() => update(form.getAttribute("action"), "POST", fields, true));
  });

  if (window.WebSocket && window.ActionCable) {
    consumer = ActionCable.createConsumer("/cable");
    consumer.subscriptions.create({ channel: "GameChannel", code: root.dataset.code, tab: phone ? tab : undefined }, {
      connected() { connected = true; lastPulse = 0; sync(); },
      disconnected() { connected = false; lastPulse = 0; schedule(1000); },
      received() { sync(); }
    });
  }
  window.addEventListener("online", sync);
  document.addEventListener("visibilitychange", () => { if (!document.hidden) sync(); });
  window.addEventListener("pagehide", () => {
    away = true;
    clearTimeout(timer);
    consumer?.disconnect();
    if (phone && !ended() && state().dataset.version !== "guest") {
      const fields = new URLSearchParams({ tab });
      if (csrf) fields.set("authenticity_token", csrf);
      navigator.sendBeacon(root.dataset.leaveUrl, fields);
    }
  });
  window.addEventListener("pageshow", event => {
    if (!event.persisted) return;
    away = false;
    syncQueued = false;
    lastPulse = 0;
    consumer?.connect();
    sync();
  });
  sync();
}

document.querySelectorAll("[data-live]").forEach(setupLiveGame);
