module Moderate
  class BaseController < ApplicationController
    layout "moderate"

    prepend_before_action :require_moderator

    private
      def require_moderator
        no_store
        username = ENV["QUIZZY_MODERATOR_USERNAME"]
        password = ENV["QUIZZY_MODERATOR_PASSWORD"]
        if username.present? && password.present?
          http_basic_authenticate_or_request_with name: username, password: password, realm: "Quizzy moderator"
        else
          request_http_basic_authentication("Quizzy moderator")
        end
      end
